// scripts/apidoc.ts — generate docs/API.md from exported symbols + JSDoc
import { readFileSync, writeFileSync, mkdirSync } from "fs";

const src = readFileSync("src/index.ts", "utf8");
const schema = readFileSync("src/schema.ts", "utf8");
const lines = src.split("\n");

const out: string[] = [
  "# AsmZod API",
  "",
  "Generated by `bun scripts/apidoc.ts`.",
  "",
  "## `z` factories",
  "",
  "| factory | doc |",
  "|---|---|",
];
let doc: string | null = null;
let inZ = false;
for (const l of lines) {
  if (l.includes("export const z = {")) inZ = true;
  if (inZ && l === "};") inZ = false;
  const dm = l.match(/^\s*\/\*\*\s*(.+?)\s*\*\/\s*$/);
  if (dm) { doc = dm[1]; continue; }
  const fm = l.match(/^\s+([a-zA-Z0-9_]+):\s/);
  if (inZ && fm) {
    out.push(`| \`z.${fm[1]}\` | ${doc ?? ""} |`);
    doc = null;
  }
}

out.push("", "## Schema classes", "");
const classes = [...schema.matchAll(/export class (Zod\w+)/g)].map((m) => m[1]);
for (const c of classes) out.push(`- \`${c}\``);

const common = [
  ".parse(v)", ".safeParse(v)", ".parseAsync(v)", ".safeParseAsync(v)",
  ".optional()", ".nullable()", ".nullish()", ".default(v)", ".catch(v)",
  ".refine(fn)", ".transform(fn)", ".pipe(s)", ".describe(s)",
];
out.push("", "## Common methods (all ZodType subclasses)", "");
for (const m of common) out.push(`- \`${m}\``);

out.push("", "## Type helpers", "",
  "- `z.infer<T>` / `z.output<T>` — parsed output type",
  "- `z.input<T>` — accepted input type",
  "",
  "## Engine", "",
  "- `engineVersion()` — engine version string",
  "- `engineBackend()` — `\"napi\" | \"ffi\" | \"portable\"`",
  "- `z.toJSONSchema(schema)` — JSON Schema draft 2020-12 export",
);

mkdirSync("docs", { recursive: true });
writeFileSync("docs/API.md", out.join("\n") + "\n");
console.log(`docs/API.md: ${out.length} lines, ${classes.length} classes`);
